INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q19611623', 'Battle of Islandbridge', 'The Battle of Islandbridge, also called the Battle of Áth Cliath, took place on 14 September 919, between a coalition of native Irish, led by Niall Glúndub, overking of the Northern Uí Néill and High King of Ireland, and the Dublin-based Vikings of the Uí Ímair, led by Sitric Cáech. It was one in a series of battles initiated by the native Irish to attempt to drive the Vikings of the Uí Ímair from Ireland.', 919, 9, 14, NULL, NULL, NULL, 'day', '14 September 919', 37, 'https://en.wikipedia.org/wiki/Battle_of_Islandbridge'),
  ('Q4562817', 'Battle of Tara', 'The Battle of Tara was fought between the Gaelic Irish of Meath, led by Máel Sechnaill mac Domnaill, and the Norse Vikings of Dublin, led by Amlaíb Cuarán. It took place near the Hill of Tara in Ireland in the year 980.', 980, NULL, NULL, NULL, NULL, NULL, 'year', '980', 34, 'https://en.wikipedia.org/wiki/Battle_of_Tara_(Ireland)'),
  ('Q1992706', 'Battle of Glenmama', 'The Battle of Glenn Máma or Glenmama (Irish: Cath Ghleann Máma, The Battle of "The Glen of the Gap") took place most probably near Lyons Hill in Ardclough, County Kildare, Ireland, in AD 999 between Windmill Hill and Blackchurch. It was the decisive and only engagement of the brief Leinster revolt of 999–1000 against the King of Munster, Brian Boru.', 999, 12, 30, NULL, NULL, NULL, 'day', '30 December 999', 34, 'https://en.wikipedia.org/wiki/Battle_of_Glenmama'),
  ('Q868027', 'Battle of Clontarf', 'The Battle of Clontarf (Irish: Cath Chluain Tarbh) took place on 23 April 1014 at Clontarf, near Dublin, on the east coast of Ireland. It pitted an army led by Brian Boru, High King of Ireland, against a Norse-Irish alliance comprising the forces of Sigtrygg Silkbeard, King of Dublin; Máel Mórda mac Murchada, King of Leinster; and a Viking army from abroad led by Sigurd of Orkney and Brodir of Mann.', 1014, 4, 23, NULL, NULL, NULL, 'day', '23 April 1014', 60, 'https://en.wikipedia.org/wiki/Battle_of_Clontarf'),
  ('Q2011697', 'Battle of Faughart', 'The Battle of Faughart (or Battle of Dundalk) was fought on 14 October 1318 between an Anglo-Irish force led by John de Bermingham (later created 1st Earl of Louth) and Edmund Butler, Earl of Carrick, and a Scottish and Irish army commanded by Prince Edward Bruce, Earl of Carrick, brother of King Robert I of Scots (''Robert the Bruce''). It was a battle of the First War of Scottish Independence and more precisely the Irish Bruce Wars.', 1318, 10, 14, NULL, NULL, NULL, 'day', '14 October 1318', 43, 'https://en.wikipedia.org/wiki/Battle_of_Faughart'),
  ('Q474399', 'Battle of Affane', 'The Battle of Affane (Irish: Cath Áth Mheáin) was fought in County Waterford, in south-eastern Ireland, in 1565, between the forces of the Fitzgerald Earl of Desmond and the Butler Earl of Ormond. The battle ended in the rout of the Desmond forces.', 1565, 2, NULL, NULL, NULL, NULL, 'month', 'February 1565', 34, 'https://en.wikipedia.org/wiki/Battle_of_Affane'),
  ('Q1431771', 'Battle of Glenmalure', 'The Battle of Glenmalure (Irish: Cath Ghleann Molúra) took place in Ireland on 25 August 1580 during the Desmond Rebellions. A Catholic army of united Irish clans from the Wicklow Mountains led by Fiach MacHugh O''Byrne and James Eustace, 3rd Viscount Baltinglass of the Pale, defeated an English army under Arthur Grey, 14th Baron Grey de Wilton, at Clan O''Byrne''s mountain stronghold of Glenmalure.', 1580, 8, 25, NULL, NULL, NULL, 'day', '25 August 1580', 39, 'https://en.wikipedia.org/wiki/Battle_of_Glenmalure'),
  ('Q1459058', 'Battle of Curlew Pass', 'The Battle of Curlew Pass was fought on 15 August 1599 during the campaign of the Earl of Essex in the Nine Years'' War, between an English force under Sir Conyers Clifford and a rebel Irish force led by Hugh Roe O''Donnell. The English were ambushed and routed while marching through a pass in the Curlew Mountains, near the town of Boyle, in the west of Ireland.', 1599, 8, 15, NULL, NULL, NULL, 'day', '15 August 1599', 41, 'https://en.wikipedia.org/wiki/Battle_of_Curlew_Pass'),
  ('Q491255', 'Siege of Kinsale', 'The siege of Kinsale (Irish: Léigear Chionn tSáile), also known as the battle of Kinsale, was the ultimate battle in England''s conquest of Gaelic Ireland, commencing in October 1601, near the end of the reign of Queen Elizabeth I, and at the climax of the Nine Years'' War—a campaign by Hugh O''Neill, Hugh Roe O''Donnell and other Irish lords against English rule. Owing to Spanish involvement and the strategic advantages to be gained, the battle also formed part of the Anglo-Spanish War, the wider conflict of Protestant England against Catholic Spain.', 1601, 10, 2, 1602, 1, 3, 'day', '2 October 1601 – 3 January 1602', 51, 'https://en.wikipedia.org/wiki/Siege_of_Kinsale'),
  ('Q3526182', 'Siege of Dunboy', 'The siege of Dunboy took place at Dunboy Castle between 5 June and 18 June 1602, during the Nine Years'' War in Ireland. It was one of the last battles of the war.', 1602, 6, 5, 1602, 6, 18, 'day', '5 June 1602 – 18 June 1602', 39, 'https://en.wikipedia.org/wiki/Siege_of_Dunboy'),
  ('Q1461147', 'Irish Rebellion of 1641', 'The Irish Rebellion of 1641 began on 23 October 1641. Initiated by Irish gentry and military officers, the rebellion sought to end English domination of Ireland, restore lands confiscated through the plantations of Ireland, and secure Irish control over the country''s government and affairs.', 1641, 10, 23, NULL, NULL, NULL, 'day', '23 October 1641', 59, 'https://en.wikipedia.org/wiki/Irish_Rebellion_of_1641'),
  ('Q497787', 'Battle of Liscarroll', 'The Battle of Liscarroll was fought on 3 September 1642 in northern County Cork, Munster, between Irish Confederate and Royalist troops. The battle was part of the Irish Confederate Wars, which had started in the north in 1641 reaching Munster in 1642.', 1642, 7, NULL, NULL, NULL, NULL, 'month', 'July 1642', 34, 'https://en.wikipedia.org/wiki/Battle_of_Liscarroll'),
  ('Q2237651', 'Battle of New Ross', 'The Battle of New Ross also known as the Battle of Ballinvegga occurred on 18 March 1643 during the Irish Confederate Wars when the Leinster Confederates commanded by Thomas Preston were routed at Ballinvegga in County Wexford by Royalist forces commanded by the Marquess of Ormond.', 1643, 3, 18, NULL, NULL, NULL, 'day', '18 March 1643', 34, 'https://en.wikipedia.org/wiki/Battle_of_New_Ross_(1643)'),
  ('Q494896', 'Battle of Dungan''s Hill', 'The Battle of Dungan''s Hill took place in County Meath, in eastern Ireland on 8 August 1647. It was fought between the armies of Confederate Ireland and the English Parliament during the Irish Confederate Wars.', 1647, 8, NULL, NULL, NULL, NULL, 'month', 'August 1647', 37, 'https://en.wikipedia.org/wiki/Battle_of_Dungan''s_Hill'),
  ('Q1478896', 'Battle of Knocknanuss', 'The Battle of Knocknanauss was fought in 1647, during the Irish Confederate Wars, part of the Wars of the Three Kingdoms, between Confederate Ireland’s Munster army and an English Parliamentarian army under Murrough O’Brien. The battle resulted in a crushing defeat for the Irish Confederates.', 1647, 11, 13, NULL, NULL, NULL, 'day', '13 November 1647', 37, 'https://en.wikipedia.org/wiki/Battle_of_Knocknanuss'),
  ('Q815226', 'Sack of Wexford', 'The Sack of Wexford took place from 2 to 11 October 1649, during the Cromwellian conquest of Ireland, part of the 1641–1653 Irish Confederate Wars. English Commonwealth forces under Oliver Cromwell stormed the town after negotiations broke down, killing most of the Irish Confederate and Royalist garrison.', 1649, 10, 2, 1649, 10, 11, 'day', '2 October 1649 – 11 October 1649', 37, 'https://en.wikipedia.org/wiki/Sack_of_Wexford'),
  ('Q815234', 'Siege of Drogheda', 'The Siege of Drogheda, 3 to 11 September 1649, took place at the start of the Cromwellian conquest of Ireland. The port of Drogheda was held by a mixed garrison of Irish Catholics and Royalists under the command of Sir Arthur Aston, when it was besieged by English Commonwealth forces under Oliver Cromwell.', 1649, 9, 3, 1649, 9, 11, 'day', '3 September 1649 – 11 September 1649', 45, 'https://en.wikipedia.org/wiki/Siege_of_Drogheda'),
  ('Q1461766', 'Battle of Rathmines', 'The Battle of Rathmines, 2 August 1649, took place outside Dublin, in the suburb of Rathmines. Part of the Irish Confederate Wars and 1639 to 1653 Wars of the Three Kingdoms, it has been described as the ''decisive battle of the Engagement in Ireland.'' In late July 1649, a combined Irish Confederate/Royalist army under the Earl of Ormond, tried to capture Dublin.', 1649, 8, 2, NULL, NULL, NULL, 'day', '2 August 1649', 37, 'https://en.wikipedia.org/wiki/Battle_of_Rathmines'),
  ('Q1672808', 'Irish Confederate Wars', 'The Irish Confederate Wars took place from 1641 to 1653. The conflict began with the Irish rising of 1641 and evolved into a prolonged struggle over Ireland''s future, as Irish forces sought to defend their land, political rights and autonomy against foreign control, plantation policies and continued encroachment on Irish self-government.', 1653, NULL, NULL, 1653, 4, NULL, 'century', '17th century', 53, 'https://en.wikipedia.org/wiki/Irish_Confederate_Wars'),
  ('Q644960', 'Battle of the Boyne', 'The Battle of the Boyne (Irish: Cath na Bóinne IPA: [ˈkah n̪ˠə ˈbˠoːn̠ʲə]) took place in 1690 between the forces of the deposed King James II, and those of King William III who, with his wife Queen Mary II (his cousin and James''s daughter), had acceded to the Crowns of England, Scotland and Ireland in 1689. The battle was fought across the River Boyne close to the town of Drogheda in the Kingdom of Ireland, modern-day Ireland, and resulted in a victory for William.', 1690, 7, 11, NULL, NULL, NULL, 'day', '11 July 1690', 70, 'https://en.wikipedia.org/wiki/Battle_of_the_Boyne'),
  ('Q2713014', 'Siege of Limerick', 'Limerick, a city in western Ireland, was besieged twice in the Williamite War in Ireland in 1689–1691. On the first occasion, in August to September 1690, its Jacobite defenders retreated to the city after their defeat at the Battle of the Boyne.', 1690, 8, NULL, 1690, 9, NULL, 'month', 'August 1690 – September 1690', 39, 'https://en.wikipedia.org/wiki/Siege_of_Limerick_(1690)'),
  ('Q494840', 'Siege of Limerick', 'The siege of Limerick in western Ireland was a second siege of the town during the Williamite War in Ireland (1689–1691). The city, held by Jacobite forces, was able to beat off a Williamite assault in 1690.', 1691, NULL, NULL, 1691, 10, NULL, 'year', '1691', 37, 'https://en.wikipedia.org/wiki/Siege_of_Limerick_(1691)'),
  ('Q1860162', 'Treaty of Limerick', 'The Treaty of Limerick (Irish: Conradh Luimnigh), signed on 3 October 1691, ended the Williamite War in Ireland, a conflict related to the Nine Years'' War (1688–1697). It consisted of two separate agreements, one with military terms of surrender, signed by commanders of a French expeditionary force and Irish Jacobites loyal to the exiled James II. Lieutenant-General de Ginkell, leader of government forces in Ireland, signed on behalf of William III and his wife Mary II. It allowed Jacobite units to be transported to France, the diaspora known as the Flight of the Wild Geese.', 1691, NULL, NULL, NULL, NULL, NULL, 'year', '1691', 51, 'https://en.wikipedia.org/wiki/Treaty_of_Limerick'),
  ('Q2887916', 'Battle of Aughrim', 'The Battle of Aughrim (Irish: Cath Eachroma) was the decisive battle of the Williamite War in Ireland. It was fought between the largely Irish Jacobite army loyal to James II and the forces of William III on 12 July 1691 (old style, equivalent to 22 July new style), near the village of Aughrim, County Galway.', 1691, 7, 22, NULL, NULL, NULL, 'day', '22 July 1691', 45, 'https://en.wikipedia.org/wiki/Battle_of_Aughrim'),
  ('Q944941', 'Irish Rebellion of 1798', 'The Irish Rebellion of 1798 (Irish: Éirí Amach 1798; Ulster Scots: "The Turn Out"/"The Hurries") was a popular insurrection against the British Crown in what was then the separate, but subordinate, Kingdom of Ireland. The main organising force was the Society of United Irishmen.', 1798, 5, 24, 1798, 9, 24, 'day', '24 May 1798 – 24 September 1798', 67, 'https://en.wikipedia.org/wiki/Irish_Rebellion_of_1798'),
  ('Q2888269', 'Battle of Castlebar', 'The Battle of Castlebar was a military engagement of the Irish Rebellion of 1798, which occurred on 27 August 1798 near the town of Castlebar, County Mayo. A combined force of approximately 800 French troops and 2,000 United Irishmen rebels, commanded by Jean Joseph Amable Humbert, routed a British Crown force numbering from 3,000 to 5,000 men, led by Gerard Lake, 1st Viscount Lake, in what would later become known as the "Castlebar Races" or "Races of Castlebar".', 1798, 8, 27, NULL, NULL, NULL, 'day', '27 August 1798', 39, 'https://en.wikipedia.org/wiki/Battle_of_Castlebar'),
  ('Q2890346', 'Battle of Vinegar Hill', 'The Battle of Vinegar Hill (Irish: Cath Chnoc Fhíodh na gCaor) was a military engagement during the Irish Rebellion of 1798 on 21 June 1798 between a force of approximately 13,000 government troops under the command of Gerard Lake and 16,000 United Irishmen rebels led by Anthony Perry. The battle, a major rebel defeat, took place on a large rebel camp on Vinegar Hill and in the streets of Enniscorthy, County Wexford and marked the last major attempt by the rebels to hold and control territory taken in Wexford.', 1798, 6, 21, NULL, NULL, NULL, 'day', '21 June 1798', 41, 'https://en.wikipedia.org/wiki/Battle_of_Vinegar_Hill'),
  ('Q3636589', 'Battle of Prosperous', 'The Battle of Prosperous was a military engagement between British Crown forces and United Irishmen rebels on 24 May 1798, during that year''s Irish Rebellion, in the town of Prosperous, County Kildare. Prosperous was founded by Sir Robert Brooke in 1780 as a village for processing cotton produced in the Americas.', 1798, 5, 24, NULL, NULL, NULL, 'day', '24 May 1798', 34, 'https://en.wikipedia.org/wiki/Battle_of_Prosperous'),
  ('Q4871883', 'Battle of New Ross', 'The Battle of New Ross was a military engagement which took place in New Ross, County Wexford during the Irish Rebellion of 1798. It was fought between the Society of United Irishmen rebels and government forces garrisoning the town.', 1798, 6, 5, NULL, NULL, NULL, 'day', '5 June 1798', 34, 'https://en.wikipedia.org/wiki/Battle_of_New_Ross_(1798)'),
  ('Q4197178', 'Irish Rebellion of 1803', 'The Irish rebellion of 1803 was an attempt by Irish republicans to seize the seat of the British government in Ireland, Dublin Castle, and trigger a nationwide insurrection. Renewing the struggle of 1798, they were organised under a reconstituted United Irish directorate.', 1803, 7, 23, NULL, NULL, NULL, 'day', '23 July 1803', 34, 'https://en.wikipedia.org/wiki/Irish_rebellion_of_1803'),
  ('Q193689', 'Easter Rising', 'The Easter Rising (Irish: Éirí Amach na Cásca), also known as the Easter Rebellion, was an armed insurrection in Ireland during Easter Week in April 1916. The Rising was launched by Irish republicans against British rule in Ireland with the aim of establishing an independent Irish Republic while the United Kingdom was fighting the First World War.', 1916, 4, NULL, 1916, 4, 29, 'month', 'April 1916 – 29 April 1916', 78, 'https://en.wikipedia.org/wiki/Easter_Rising'),
  ('Q886799', 'Bloody Sunday', 'Bloody Sunday (Irish: Domhnach na Fola) was a day of violence in Dublin on 21 November 1920, during the Irish War of Independence. More than 30 people were killed or fatally wounded.', 1920, 11, 21, NULL, NULL, NULL, 'day', '21 November 1920', 60, 'https://en.wikipedia.org/wiki/Bloody_Sunday_(1920)'),
  ('Q645776', 'Battle of Dublin', 'The Battle of Dublin was a week of street battles in Dublin from 28 June to 5 July 1922 that marked the beginning of the Irish Civil War. Six months after the Anglo-Irish Treaty ended the recent Irish War of Independence, it was fought between the forces of the new Provisional Government and a section of the Irish Republican Army (IRA) that opposed the Treaty.', 1922, 6, 28, 1922, 7, 5, 'day', '28 June 1922 – 5 July 1922', 61, 'https://en.wikipedia.org/wiki/Battle_of_Dublin'),
  ('Q748042', 'Irish Civil War', 'The Irish Civil War (Irish: Cogadh Cathartha na hÉireann; 28 June 1922 – 24 May 1923) was a conflict that followed the Irish War of Independence and accompanied the establishment of the Irish Free State, an entity independent from the United Kingdom but within the British Empire. The civil war was waged between the Provisional Government of Ireland and the Anti-Treaty IRA over the Anglo-Irish Treaty.', 1922, 6, 28, 1923, 5, 24, 'day', '28 June 1922 – 24 May 1923', 76, 'https://en.wikipedia.org/wiki/Irish_Civil_War'),
  ('Q113213574', 'assassination of Louis Mountbatten, 1st Earl Mountbatten of Burma', 'Lord Mountbatten, a retired British statesman and cousin to Queen Elizabeth II, was assassinated on 27 August 1979 off the coast of Mullaghmore, Ireland. Thomas McMahon, an Irish republican and a volunteer for the Provisional Irish Republican Army (IRA), planted a bomb on Mountbatten''s boat, the cabin cruiser Shadow V, during Mountbatten''s annual summer trip to Classiebawn Castle, his house on the Mullaghmore Peninsula.', 1979, 8, 27, NULL, NULL, NULL, 'day', '27 August 1979', 41, 'https://en.wikipedia.org/wiki/Assassination_of_Lord_Mountbatten'),
  ('Q2708643', 'Anglo-Irish Agreement', 'The Anglo-Irish Agreement was a 1985 treaty between the United Kingdom and the Republic of Ireland which aimed to help bring an end to the Troubles in Northern Ireland. The treaty gave the Irish government an advisory role in Northern Ireland''s government while confirming that there would be no change in the constitutional position of Northern Ireland unless a majority of its citizens agreed to join the Republic.', 1985, 11, 15, NULL, NULL, NULL, 'day', '15 November 1985', 48, 'https://en.wikipedia.org/wiki/Anglo-Irish_Agreement'),
  ('Q855736', 'Celtic Tiger', 'The "Celtic Tiger" (Irish: An Tíogar Ceilteach) is a term referring to the economy of Ireland from the mid-1990s to the end of the first decade of the 21st century, a period of rapid real economic growth fuelled by foreign direct investment. The boom was dampened by a subsequent property bubble in 2007 which brought forth a severe economic downturn culminating in 2008''s Great Recession.', 1994, NULL, NULL, 2007, NULL, NULL, 'year', '1994–2007', 65, 'https://en.wikipedia.org/wiki/Celtic_Tiger'),
  ('Q5438752', 'Manx2 Flight 7100', 'Manx2 Flight 7100 was a scheduled commercial flight from Belfast, Northern Ireland, to Cork, Republic of Ireland. On 10 February 2011, the Fairchild Metro III aircraft flying the route with ten passengers and two crew on board crashed on its third attempt to land at Cork Airport in foggy conditions.', 2011, 2, 10, NULL, NULL, NULL, 'day', '10 February 2011', 48, 'https://en.wikipedia.org/wiki/Manx2_Flight_7100'),
  ('Q15991234', 'Treaty Establishing the European Stability Mechanism', 'The Treaty Establishing the European Stability Mechanism was signed by the member states of the eurozone to found the European Stability Mechanism (ESM), an international organisation located in Luxembourg, to act as a permanent source of financial assistance for member states in financial difficulty, with a maximum lending capacity of €500 billion. It replaced two earlier temporary EU funding programmes: the European Financial Stability Facility (EFSF) and the European Financial Stabilisation Mechanism (EFSM).', 2012, 2, 2, NULL, NULL, NULL, 'day', '2 February 2012', 34, 'https://en.wikipedia.org/wiki/Treaty_establishing_the_European_Stability_Mechanism'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q123521339', '2023 Dublin riot', 'On the evening of 23 November 2023, a riot took place in Dublin, Ireland, which involved multiple incidents of vandalism, arson, and looting in the city centre as well as assaults on Gardaí (Irish police) and members of the public. Gardaí described the riot as the most violent in modern Dublin history, far surpassing the 2006 riots.', 2023, 11, 23, 2023, 11, 24, 'day', '23 November 2023 – 24 November 2023', 47, 'https://en.wikipedia.org/wiki/2023_Dublin_riot');
